public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(required=true label='Email')
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id')
        public Id contactId;

        @InvocableVariable(label='Found')
        public Boolean found;

        public Result() {
            this.found = false;
            this.contactId = null;
        }
    }

    @InvocableMethod(label='Find Contact by Email' description='Finds an existing Contact by email address, matching case-insensitively.')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null || requests.isEmpty()) {
            return results;
        }

        List<String> normalizedEmails = new List<String>(requests.size());
        Set<String> emailsToFind = new Set<String>();

        for (Request req : requests) {
            String normalized = null;
            if (req != null && !String.isBlank(req.email)) {
                normalized = req.email.trim().toLowerCase();
                if (!String.isBlank(normalized)) {
                    emailsToFind.add(normalized);
                } else {
                    normalized = null;
                }
            }
            normalizedEmails.add(normalized);
            results.add(new Result());
        }

        if (emailsToFind.isEmpty()) {
            return results;
        }

        // Do not rely on SOQL text comparison for the email match.
        // SOQL equality / IN with bind variables does not reliably give a
        // case-insensitive exact match for every stored value (for example
        // values stored in mixed case, or with surrounding whitespace),
        // so filtering with WHERE Email IN :emails or LIKE can return no
        // rows even though a matching Contact exists. Instead, perform
        // the single bulkified query below and do the exact matching in
        // Apex, where both the stored email and the requested email are
        // trimmed and lower-cased before comparison. This guarantees
        // case-insensitive, whitespace-tolerant matching, uses at most
        // one SOQL query for the whole batch, and, because the class is
        // 'with sharing', only returns Contacts visible to the running
        // user under their sharing rules.
        Map<String, Id> earliestContactIdByEmail = new Map<String, Id>();

        // Ordered oldest first, so the first Contact seen for an email
        // is the one with the earliest CreatedDate and wins.
        for (Contact con : [
            SELECT Id, Email
            FROM Contact
            WHERE Email != null
            ORDER BY CreatedDate ASC, Id ASC
        ]) {
            if (String.isBlank(con.Email)) {
                continue;
            }
            String key = con.Email.trim().toLowerCase();
            if (emailsToFind.contains(key) && !earliestContactIdByEmail.containsKey(key)) {
                earliestContactIdByEmail.put(key, con.Id);
                if (earliestContactIdByEmail.size() == emailsToFind.size()) {
                    break;
                }
            }
        }

        for (Integer i = 0; i < requests.size(); i++) {
            String normalized = normalizedEmails[i];
            if (normalized != null && earliestContactIdByEmail.containsKey(normalized)) {
                results[i].contactId = earliestContactIdByEmail.get(normalized);
                results[i].found = true;
            } else {
                results[i].contactId = null;
                results[i].found = false;
            }
        }

        return results;
    }
}
