    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        return new List<Schema.SObjectField>{
            Opportunity.Id,
            Opportunity.Name,
            Opportunity.AccountId,
            Opportunity.StageName,
            Opportunity.Amount,
            Opportunity.CloseDate
        };
    }

    public List<Opportunity> selectById(Set<Id> opportunityIds) {
        return (List<Opportunity>) selectSObjectsById(opportunityIds);
    }

    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        if (accountIds == null || accountIds.isEmpty() || maxRecords == null || maxRecords <= 0) {
            return new List<Opportunity>();
        }

        // Build from the selector's query factory so the standard field
        // list and the selector's CRUD/FLS security settings are applied.
        // This version of fflib_QueryFactory has no clearOrdering /
        // clearOrderings (or setOrdering) method, so the factory's default
        // ORDER BY (from getOrderBy(), i.e. Name) cannot be removed via
        // the factory API. It is therefore stripped from the generated
        // SOQL and replaced with the required ordering and limit below.
        fflib_QueryFactory queryFactory = newQueryFactory()
            .selectField('Account.Name')
            .setCondition('AccountId IN :accountIds AND IsClosed = false');

        String soql = queryFactory.toSOQL();

        Integer orderByIndex = soql.toUpperCase().indexOf(' ORDER BY ');
        if (orderByIndex >= 0) {
            soql = soql.substring(0, orderByIndex);
        }

        // maxRecords is a validated Integer (> 0), so inlining it is safe.
        // Amount DESC NULLS LAST puts opportunities without an Amount
        // after all others; CloseDate ASC breaks amount ties.
        soql += ' ORDER BY Amount DESC NULLS LAST, CloseDate ASC LIMIT ' + maxRecords;

        return (List<Opportunity>) Database.query(soql);
    }
