public class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> result = new List<Id>();
        if (requests == null || requests.isEmpty()) {
            return result;
        }

        // Validate ALL requests before any DML.
        for (GiftRequest req : requests) {
            if (req == null) {
                throw new RecurringGiftException('Gift request must not be null.');
            }
            if (req.contactId == null) {
                throw new RecurringGiftException('Contact is required for every recurring gift.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException('Amount must be a positive value for every recurring gift.');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                throw new RecurringGiftException('Day of month must be between 1 and 31.');
            }
            if (req.startDate == null) {
                throw new RecurringGiftException('Start date is required for every recurring gift.');
            }
        }

        // Enhanced Recurring Donations has its own last-day-of-month
        // representation on npsp__Day_of_Month__c (a restricted picklist),
        // which is not the literal string 'Last Day' in this org. Discover
        // the actual active picklist value at runtime via Schema describe
        // (no SOQL/DML used), and pair it with
        // npsp__Always_Use_Last_Day_Of_Month__c.
        // 29 and 30 (and 1-28) are stored as those literal days.
        String lastDayValue = null;
        String nonNumericValue = null;
        Schema.DescribeFieldResult dayDescribe =
            npe03__Recurring_Donation__c.npsp__Day_of_Month__c.getDescribe();
        for (Schema.PicklistEntry entry : dayDescribe.getPicklistValues()) {
            if (!entry.isActive()) {
                continue;
            }
            String v = entry.getValue();
            String l = entry.getLabel();
            if ((v != null && v.toLowerCase().contains('last')) ||
                (l != null && l.toLowerCase().contains('last'))) {
                lastDayValue = v;
                break;
            }
            // Remember any non-numeric entry as a fallback candidate:
            // the only non-numeric day-of-month option is the
            // last-day-of-month option.
            if (v != null && !v.isNumeric() && nonNumericValue == null) {
                nonNumericValue = v;
            }
        }
        if (lastDayValue == null) {
            lastDayValue = nonNumericValue;
        }

        List<npe03__Recurring_Donation__c> donations = new List<npe03__Recurring_Donation__c>();

        for (GiftRequest req : requests) {
            Boolean isOpenEnded = (req.installments == null || req.installments == 0);
            Boolean isLastDay = (req.dayOfMonth == 31);

            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c();
            // Donor
            rd.npe03__Contact__c = req.contactId;
            rd.npe03__Organization__c = null;

            // Amount per installment
            rd.npe03__Amount__c = req.amount;

            // Monthly schedule, every 1 month, on dayOfMonth
            rd.npe03__Installment_Period__c = 'Monthly';
            rd.npsp__InstallmentFrequency__c = 1;
            rd.npe03__Schedule_Type__c = 'Multiply By';

            // "31" means last day of the month in Enhanced Recurring Donations.
            // 29 and 30 are stored as those literal days.
            if (isLastDay) {
                rd.npsp__Always_Use_Last_Day_Of_Month__c = true;
                if (lastDayValue != null) {
                    rd.npsp__Day_of_Month__c = lastDayValue;
                } else {
                    // Fallback if the org has no explicit "last" picklist
                    // entry: 31 paired with Always_Use_Last_Day_Of_Month.
                    rd.npsp__Day_of_Month__c = '31';
                }
            } else {
                rd.npsp__Day_of_Month__c = String.valueOf(req.dayOfMonth);
                rd.npsp__Always_Use_Last_Day_Of_Month__c = false;
            }

            // Dates / status
            rd.npsp__StartDate__c = req.startDate;
            rd.npe03__Date_Established__c = req.startDate;
            rd.npe03__Next_Payment_Date__c = req.startDate;
            rd.npsp__Status__c = 'Active';
            rd.npsp__PaymentMethod__c = req.paymentMethod;

            // Open-ended vs fixed-length
            if (isOpenEnded) {
                rd.npsp__RecurringType__c = 'Open';
                rd.npe03__Open_Ended_Status__c = 'Open';
                rd.npe03__Installments__c = null;
                rd.npsp__EndDate__c = null;
            } else {
                rd.npsp__RecurringType__c = 'Fixed';
                rd.npe03__Open_Ended_Status__c = 'None';
                rd.npe03__Installments__c = req.installments;
                // Let NPSP/RD2 derive npsp__EndDate__c from the start date,
                // frequency, day of month and number of installments.
            }

            donations.add(rd);
        }

        // Single DML statement; NPSP (RD2) generates installment
        // Opportunities itself. Do not create Opportunities here.
        insert donations;

        for (npe03__Recurring_Donation__c rd : donations) {
            result.add(rd.Id);
        }
        return result;
    }
